// SAOS Cold Email Sequence — Prospect Data + Personalization
// This node holds sample prospect data as a placeholder.
// In production, replace with Google Sheets Read or HTTP Request to fetch from CRM.

const prospects = [
  {
    first_name: "Marcus",
    last_name: "Chen",
    company_name: "Copper Kettle Group",
    industry: "Restaurant",
    email: "marcus.chen@copperkettlegroup.com",
    pain_points: "12 locations run on spreadsheets; no centralized inventory; managers text orders manually; 18% food waste variance",
    current_tools: "Toast POS, Google Sheets, WhatsApp groups",
    tier: "Enterprise",
    priority_score: 9,
    contacted: false
  },
  {
    first_name: "Jim",
    last_name: "Harrison",
    company_name: "Midwest Fulfillment Partners",
    industry: "3PL",
    email: "jim.harrison@midwestfulfillment.com",
    pain_points: "NetSuite configured but staff uses spreadsheets for 60% of ops; no automated SLA compliance tracking; chargeback disputes take 3 weeks",
    current_tools: "ShipStation, NetSuite, Zoho CRM",
    tier: "Enterprise",
    priority_score: 10,
    contacted: false
  },
  {
    first_name: "Kevin",
    last_name: "Liu",
    company_name: "Brightpath Accounting Group",
    industry: "Accounting",
    email: "kevin.liu@brightpathaccounting.com",
    pain_points: "Client document collection is endless email threads; 40% of tax season chasing documents; no client portal",
    current_tools: "Lacerte, QuickBooks, Smartsheet",
    tier: "Business",
    priority_score: 9,
    contacted: false
  }
];

// Filter out already-contacted prospects
const newProspects = prospects.filter(p => !p.contacted);

// Build personalized emails for each prospect
const personalizedEmails = newProspects.map(prospect => {
  const industryLabel = prospect.industry === "3PL" ? "logistics" : prospect.industry.toLowerCase();

  // Email 1 — Initial (Pain-Driven)
  const email1Subject = `Your ${industryLabel} staff is doing data entry`;
  const email1Body = `Hey ${prospect.first_name},

Your team didn't get into this business to key invoices into spreadsheets.

Most ${industryLabel} operators I talk to are losing 8–12 hours a week to manual document processing, reconciliation, and chasing down approvals. That time doesn't show up on a P&L, but it shows up in your labor costs and your sanity.

Here's what I'm seeing at ${prospect.company_name}: ${prospect.pain_points}.

SAOS automates the paperwork so your team can focus on what matters — not forms.

Worth a 15-minute conversation?

Green Phillips
Founder, SyStack`;

  // Email 2 — Follow-up (Case Study, Day 3)
  const email2Subject = `How a similar ${industryLabel} company reclaimed 10 hours/week`;
  const email2Body = `Hi ${prospect.first_name},

A ${industryLabel} company with similar operations was drowning in manual paperwork. Their managers were coming in early just to reconcile accounts.

We automated their document intake, classification, and approval routing. They got their mornings back. No new hires, no new software to manage.

They hit breakeven in 3 weeks.

If that sounds like something worth exploring for ${prospect.company_name}, let me know.

Green Phillips
Founder, SyStack`;

  // Email 3 — Breakup (Day 10)
  const email3Subject = `Permission to close your file?`;
  const email3Body = `Hi ${prospect.first_name},

I've reached out a couple times about automating your back-office paperwork. No pressure — if the timing isn't right, I get it.

If it's a "not now," just reply "later" and I'll check back in a few months.

If it's a "never," reply "no thanks" and you'll never hear from me again.

Either way, good luck with ${prospect.company_name}.

Green Phillips
Founder, SyStack`;

  return {
    prospect: prospect,
    email1: { subject: email1Subject, body: email1Body, to: prospect.email },
    email2: { subject: email2Subject, body: email2Body, to: prospect.email },
    email3: { subject: email3Subject, body: email3Body, to: prospect.email }
  };
});

return personalizedEmails;

